&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Range of motion/exercises&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Assisting with ambulation (&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Transfers/use of mechanical lifting devices)&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Medication reminders&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;Vital sign checks: temperature, pulse, respiration&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:254}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
